177	Vec2 PhysicsHelper::computePolygonCenter(const Vec2* verts, int count)
178	{
179	    if (verts == nullptr || count <= 0)
180	        return Vec2::ZERO;
181	
182	    if (count == 1)
183	        return verts[0];
184	
185	    if (count == 2)
186	        return (verts[0] + verts[1]) * 0.5f;
187	
188	    if (polygonArea(verts, count) > kHelperEpsilon)
189	    {
190	        std::vector<cpVect> cpvs(count);
191	        points2cpvs(verts, cpvs.data(), count);
192	        return cpv2point(cpCentroidForPoly(count, cpvs.data()));
193	    }
194	
195	    // Degenerate (zero area) outline, fall back to the average of the vertices.
196	    Vec2 sum(0.0f, 0.0f);
197	    for (int i = 0; i < count; ++i)
198	    {
199	        sum += verts[i];
200	    }
201	
202	    return sum / static_cast<float>(count);
203	}
204	
205	bool PhysicsHelper::isPolygonConvex(const Vec2* verts, int count)
206	{
207	    if (verts == nullptr || count < 3)
208	        return false;
209	
210	    int sign = 0;
211	    for (int i = 0; i < count; ++i)
212	    {
213	        const Vec2& a = verts[i];
214	        const Vec2& b = verts[(i + 1) % count];
215	        const Vec2& c = verts[(i + 2) % count];
216	        const float turn = (b - a).cross(c - b);
217	
218	        if (turn > kHelperEpsilon)
219	        {
220	            if (sign < 0)
221	                return false;
222	            sign = 1;
223	        }
224	        else if (turn < -kHelperEpsilon)
225	        {
226	            if (sign > 0)
227	                return false;
228	            sign = -1;
229	        }
230	    }
231	
232	    return sign != 0;
233	}
234	
235	bool PhysicsHelper::segmentIntersect(const Vec2& a1, const Vec2& a2, const Vec2& b1, const Vec2& b2, Vec2* intersection)
236	{
237	    const Vec2 r = a2 - a1;
238	    const Vec2 s = b2 - b1;
239	    const float denom = r.cross(s);
240	
241	    if (std::fabs(denom) < kHelperEpsilon)
242	        return false;
243	
244	    const Vec2 d = b1 - a1;
245	    const float t = d.cross(s) / denom;
246	    const float u = d.cross(r) / denom;
247	
248	    if (t < 0.0f || t > 1.0f || u < 0.0f || u > 1.0f)
249	        return false;
250	
251	    if (intersection != nullptr)
252	    {
253	        *intersection = a1 + r * t;
254	    }
255	
256	    return true;
257	}
258	
259	float PhysicsHelper::pointToSegmentDistance(const Vec2& point, const Vec2& segA, const Vec2& segB)
260	{
261	    const Vec2 ab = segB - segA;
262	    const float lengthSq = ab.getLengthSq();
263	
264	    if (lengthSq < kHelperEpsilon)
265	        return (point - segA).getLength();
266	
267	    const float t = clampf((point - segA).dot(ab) / lengthSq, 0.0f, 1.0f);
268	
269	    return (point - (segA + ab * t)).getLength();
270	}
271	
272	float PhysicsHelper::polygonArea(const Vec2* verts, int count)
273	{
274	    if (verts == nullptr || count < 3)
275	        return 0.0f;
276	
277	    float sum = 0.0f;
278	    for (int i = 0; i < count; ++i)
279	    {
280	        sum += verts[i].cross(verts[(i + 1) % count]);
281	    }
282	
283	    return std::fabs(sum) * 0.5f;
284	}
285	
286	float PhysicsHelper::polygonMoment(float mass, const Vec2* verts, int count, const Vec2& offset)
287	{
288	    if (verts == nullptr || count < 3)
289	        return 0.0f;
290	
291	    std::vector<cpVect> cpvs(count);
292	    points2cpvs(verts, cpvs.data(), count);
293	
294	    return cpfloat2float(cpMomentForPoly(mass, count, cpvs.data(), point2cpv(offset), 0.0f));
295	}
296	
297	float PhysicsHelper::circleArea(float radius)
298	{
299	    return cpfloat2float(cpAreaForCircle(0, radius));
300	}
301	
302	float PhysicsHelper::circleMoment(float mass, float radius, const Vec2& offset)
303	{
304	    return cpfloat2float(cpMomentForCircle(mass, 0, radius, point2cpv(offset)));
305	}
306	
307	NS_CC_END
308	
309	#endif // CC_USE_PHYSICS

